// src/pages/Register.jsx
import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate, Link } from 'react-router-dom';
import './Register.css'; // Fichier CSS pour les styles

function Register() {
  const [nom, setNom] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('student');
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    
    try {
      const res = await axios.post('http://localhost:5000/api/auth/register', {
        nom, email, password, role
      });
      alert('Inscription réussie !');
      navigate('/login');
    } catch (err) {
      console.error(err);
      alert('Erreur inscription: ' + err.response?.data?.msg || err.message);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="register-container">
      <div className="register-card">
        <div className="register-header">
          <h2>Créer un compte</h2>
          <p>Rejoignez notre plateforme d'apprentissage</p>
        </div>

        <form onSubmit={handleSubmit} className="register-form">
          <div className="form-group">
            <label htmlFor="nom">Nom complet</label>
            <input 
              id="nom"
              type="text" 
              placeholder="Votre nom complet" 
              value={nom} 
              onChange={e => setNom(e.target.value)} 
              required 
              className="form-input"
            />
          </div>

          <div className="form-group">
            <label htmlFor="email">Adresse email</label>
            <input 
              id="email"
              type="email" 
              placeholder="exemple@email.com" 
              value={email} 
              onChange={e => setEmail(e.target.value)} 
              required 
              className="form-input"
            />
          </div>

          <div className="form-group">
            <label htmlFor="password">Mot de passe</label>
            <input 
              id="password"
              type="password" 
              placeholder="Votre mot de passe" 
              value={password} 
              onChange={e => setPassword(e.target.value)} 
              required 
              className="form-input"
            />
          </div>

          <div className="form-group">
            <label htmlFor="role">Je suis</label>
            <select 
              id="role"
              value={role} 
              onChange={e => setRole(e.target.value)}
              className="form-select"
            >
              <option value="student">👨‍🎓 Étudiant</option>
              <option value="prof">👨‍🏫 Professeur</option>
            </select>
          </div>

          <button 
            type="submit" 
            className={`submit-btn ${isLoading ? 'loading' : ''}`}
            disabled={isLoading}
          >
            {isLoading ? 'Inscription en cours...' : "S'inscrire"}
          </button>
        </form>

        <div className="register-footer">
          <p>
            Déjà un compte ? <Link to="/login" className="login-link">Se connecter</Link>
          </p>
        </div>
      </div>
    </div>
  );
}

export default Register;
